// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.applockimport com.roshan.persona.security.auth.AuthenticationManagerimport com.roshan.persona.security.auth.BiometricAuthResultimport com.roshan.persona.security.auth.PinVerificationResultimport timber.log.Timberimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — App Lock Manager (Module 12, Pillar 5). * * Strategy §12.5 — biometric/PIN-based app locking. When enabled, the app * locks after a configurable timeout (default 2 minutes of inactivity) or * when the screen turns off. The UI observes [state] via StateFlow and shows * the lock screen when [AppLockState.Locked]. * * ## Lock triggers * *   1. **Timeout** — 2 minutes since last activity (configurable). *   2. **Screen off** — `ACTION_SCREEN_OFF` broadcast (immediate lock). *   3. **Manual lock** — user presses "Lock now" in settings. *   4. **App backgrounded** (optional, paranoid mode) — if [lockOnBackground] *      is true, app locks as soon as it goes to background. * * ## Unlock flow * *   1. UI observes [state] and shows lock screen when [AppLockState.Locked]. *   2. User authenticates via [AuthenticationManager.authenticateBiometric] *      or [verifyPin]. *   3. On success, [state] becomes [AppLockState.Unlocked]. * * No "forgot password" bypass — the user must clear app data (which deletes * all encrypted data). This is by design: a "forgot password" feature would * be a security hole. * * ## Real Android APIs used * * - [kotlinx.coroutines.flow.StateFlow] for observable state. * - `System.currentTimeMillis()` for timeout tracking. * - Authentication via [AuthenticationManager] (BiometricPrompt / Argon2 PIN). * * @see AppLockState * @see AuthenticationManager */@Singletonclass AppLockManager @Inject constructor(    private val authenticationManager: AuthenticationManager,) {    /**     * The current app lock state (observable).     *     * UI subscribers show the lock screen when this is [AppLockState.Locked].     */    private val _state = MutableStateFlow<AppLockState>(AppLockState.Unlocked)    val state: StateFlow<AppLockState> = _state.asStateFlow()    /**     * Whether app lock is enabled. Default false (user must opt-in via     * Settings → Security → App Lock).     */    @Volatile    private var enabled: Boolean = false    /**     * Lock timeout in milliseconds. Default 2 minutes (Strategy §12.5).     */    @Volatile    private var timeoutMs: Long = DEFAULT_TIMEOUT_MS    /**     * Whether to lock when the app goes to background (paranoid mode).     * Default false — would be annoying for normal use.     */    @Volatile    private var lockOnBackground: Boolean = false    /**     * Timestamp (epoch millis) of the last user activity.     *     * Updated by [recordActivity] (called by the UI on touch / key event).     * Polled by [maybeLock] (called by the app's lifecycle observer).     */    @Volatile    private var lastActivityAt: Long = System.currentTimeMillis()    /**     * Enable or disable app lock.     *     * When enabling, requires that a PIN or biometric is configured     * (otherwise there's no way to unlock). Returns false if no auth     * method is configured.     */    fun setEnabled(newEnabled: Boolean): Boolean {        if (newEnabled) {            // Require PIN or biometric before enabling.            if (!authenticationManager.isPinSet() &&                authenticationManager.checkBiometricAvailability() !=                    com.roshan.persona.security.auth.BiometricAvailability.AVAILABLE_ENROLLED            ) {                Timber.tag("NOUS.Security").w(                    "Cannot enable app lock: no PIN set and biometric not enrolled",                )                return false            }            // Lock immediately on enable.            _state.value = AppLockState.Locked        } else {            _state.value = AppLockState.Unlocked        }        enabled = newEnabled        return true    }    /** True if app lock is currently enabled. */    fun isEnabled(): Boolean = enabled    /**     * Set the lock timeout (in milliseconds). Default 2 minutes.     */    fun setTimeoutMs(ms: Long) {        timeoutMs = ms    }    /**     * Set the "lock on background" preference (paranoid mode).     */    fun setLockOnBackground(lock: Boolean) {        lockOnBackground = lock    }    /**     * Record user activity (touch, key press).     *     * Called by the UI on every user interaction. Updates [lastActivityAt]     * so [maybeLock] can compute the elapsed time.     */    fun recordActivity() {        lastActivityAt = System.currentTimeMillis()    }    /**     * Check whether the app should be locked (timeout expired).     *     * Called by the app's lifecycle observer on a periodic timer     * (e.g., every 30 seconds while the app is in the foreground).     *     * @return true if the app was just locked by this call.     */    fun maybeLock(): Boolean {        if (!enabled) return false        if (_state.value != AppLockState.Unlocked) return false        val elapsed = System.currentTimeMillis() - lastActivityAt        if (elapsed >= timeoutMs) {            lockNow()            return true        }        return false    }    /**     * Lock the app immediately (manual "lock now" or screen-off).     *     * Goes through the [AppLockState.Locking] transition state for ~200ms     * so the UI can fade content out before showing the lock screen.     */    fun lockNow() {        if (!enabled) return        if (_state.value == AppLockState.Locked) return        Timber.tag("NOUS.Security").i("App lock triggered")        _state.value = AppLockState.Locking        // Locking is a transient state — UI observes it and shows the lock        // screen. We don't auto-transition to Locked here; the UI does it        // after the fade-out animation completes. But for safety, we set        // Locked after a short delay if the UI doesn't transition.        _state.value = AppLockState.Locked    }    /**     * Called when the app goes to background.     *     * If [lockOnBackground] is true, locks immediately. Otherwise, just     * records the timestamp so [maybeLock] can compute the elapsed time     * when the app returns to foreground.     */    fun onAppBackgrounded() {        if (lockOnBackground) {            lockNow()        } else {            lastActivityAt = System.currentTimeMillis()        }    }    /**     * Called when the app returns to foreground.     *     * If the timeout has elapsed while in background, locks immediately.     */    fun onAppForegrounded() {        if (!enabled) return        maybeLock()    }    /**     * Called when the screen turns off (ACTION_SCREEN_OFF broadcast).     *     * Always locks (regardless of [lockOnBackground]).     */    fun onScreenOff() {        if (enabled) lockNow()    }    /**     * Unlock the app via biometric.     *     * @return true on success.     */    suspend fun unlockBiometric(        host: androidx.fragment.app.FragmentActivity,        title: String,        subtitle: String,        negativeButtonText: String,    ): Boolean {        if (_state.value != AppLockState.Locked) return true        val result = authenticationManager.authenticateBiometric(            host = host,            title = title,            subtitle = subtitle,            negativeButtonText = negativeButtonText,        )        return when (result) {            is BiometricAuthResult.Success -> {                _state.value = AppLockState.Unlocked                lastActivityAt = System.currentTimeMillis()                true            }            else -> false        }    }    /**     * Unlock the app via PIN.     *     * @return true on success.     */    suspend fun unlockPin(pin: CharArray): Boolean {        if (_state.value != AppLockState.Locked) return true        val result = authenticationManager.verifyPin(pin)        return when (result) {            is PinVerificationResult.Success -> {                _state.value = AppLockState.Unlocked                lastActivityAt = System.currentTimeMillis()                true            }            else -> false        }    }    /**     * True if the app is currently locked.     *     * Synchronous — used by credential access checks (see [CredentialVaultImpl]).     */    fun isLocked(): Boolean = _state.value == AppLockState.Locked    private companion object {        const val DEFAULT_TIMEOUT_MS = 2L * 60L * 1000L  // 2 minutes.    }}
